#include <bits/stdc++.h>
using namespace std;
int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    auto T0=chrono::steady_clock::now();
    auto elapsed=[&]{return chrono::duration<double>(chrono::steady_clock::now()-T0).count();};
    int N; cin>>N;
    vector<double> cx(N),cy(N);
    for(int i=0;i<N;i++) cin>>cx[i]>>cy[i];
    vector<bool> isp(N,false);
    {vector<bool> s(N,true);if(N>0)s[0]=false;if(N>1)s[1]=false;
     for(int i=2;(long long)i*i<N;i++)if(s[i])for(int j=i*i;j<N;j+=i)s[j]=false;
     isp=s;}
    auto dist=[&](int a,int b)->double{double dx=cx[a]-cx[b],dy=cy[a]-cy[b];return sqrt(dx*dx+dy*dy);};
    auto pen=[&](int step,int src)->double{return(step%10==0&&!isp[src])?1.1:1.0;};
    // step s: edge from tour[s-1] to tour[s], penalty based on step s and src=tour[s-1]
    auto eCost=[&](const vector<int>&t,int s)->double{return dist(t[s-1],t[s])*pen(s,t[s-1]);};
    auto fullCost=[&](const vector<int>&t)->double{double c=0;for(int s=1;s<=N;s++)c+=eCost(t,s);return c;};
    // NN tour
    vector<int> tour(N+1);
    {vector<bool> vis(N,false);tour[0]=0;vis[0]=true;
     for(int step=1;step<N;step++){int last=tour[step-1];int best=-1;double bd=1e30;
       for(int i=0;i<N;i++)if(!vis[i]){double d=dist(last,i);if(d<bd){bd=d;best=i;}}
       tour[step]=best;vis[best]=true;}
     tour[N]=0;}
    double curCost=fullCost(tour);
    // Build nearest neighbor lists
    int KN=min(N-1,20);
    vector<vector<int>> nn(N);
    if(N<=5000){
        for(int i=0;i<N;i++){vector<pair<double,int>>v;for(int j=0;j<N;j++)if(j!=i)v.push_back({dist(i,j),j});
        sort(v.begin(),v.end());nn[i].resize(min((int)v.size(),KN));for(int k=0;k<(int)nn[i].size();k++)nn[i][k]=v[k].second;}
    } else {
        // grid-based
        double mnx=1e30,mxx=-1e30,mny=1e30,mxy=-1e30;
        for(int i=0;i<N;i++){mnx=min(mnx,cx[i]);mxx=max(mxx,cx[i]);mny=min(mny,cy[i]);mxy=max(mxy,cy[i]);}
        int gs=max(1,(int)sqrt((double)N/4.0));double cw=(mxx-mnx)/gs+1e-9,ch=(mxy-mny)/gs+1e-9;
        if(cw<1e-12)cw=1;if(ch<1e-12)ch=1;
        vector<vector<int>>grid(gs*gs);
        auto cell=[&](int id,int&gx,int&gy){gx=min(gs-1,(int)((cx[id]-mnx)/cw));gy=min(gs-1,(int)((cy[id]-mny)/ch));};
        for(int i=0;i<N;i++){int gx,gy;cell(i,gx,gy);grid[gy*gs+gx].push_back(i);}
        for(int i=0;i<N;i++){int gx0,gy0;cell(i,gx0,gy0);vector<pair<double,int>>cd;
          for(int r=0;r<gs*2&&(int)cd.size()<KN*5;r++)for(int dx=-r;dx<=r;dx++)for(int dy=-r;dy<=r;dy++){
            if(abs(dx)!=r&&abs(dy)!=r)continue;int gx=gx0+dx,gy=gy0+dy;if(gx<0||gx>=gs||gy<0||gy>=gs)continue;
            for(int id:grid[gy*gs+gx])if(id!=i)cd.push_back({dist(i,id),id});}
          sort(cd.begin(),cd.end());nn[i].resize(min((int)cd.size(),KN));for(int k=0;k<(int)nn[i].size();k++)nn[i][k]=cd[k].second;}
    }
    vector<int> pos(N);
    auto bpos=[&]{for(int i=0;i<N;i++)pos[tour[i]]=i;};
    bpos();
    double bestCost=curCost;vector<int>bestTour=tour;
    // 2-opt
    auto do2opt=[&](int i,int j)->bool{
        if(i<1||j>=N||i>=j)return false;
        double oldC=0;for(int s=i;s<=min(j+1,N);s++)oldC+=eCost(tour,s);
        reverse(tour.begin()+i,tour.begin()+j+1);
        double newC=0;for(int s=i;s<=min(j+1,N);s++)newC+=eCost(tour,s);
        if(newC<oldC-1e-10){curCost+=newC-oldC;for(int s=i;s<=j;s++)pos[tour[s]]=s;return true;}
        reverse(tour.begin()+i,tour.begin()+j+1);return false;};
    for(int pass=0;pass<100&&elapsed()<4.7;pass++){
        bool imp=false;
        for(int i=1;i<N-1&&elapsed()<4.7;i++){
            int ci=tour[i];
            for(int nb:nn[ci]){int j=pos[nb];
                if(j<=i)continue;if(j>=N)continue;if(j-i>300)continue;
                if(do2opt(i,j)){imp=true;break;}}
            // also try i-1 neighbors
            if(i>0){int cp=tour[i-1];for(int nb:nn[cp]){int j=pos[nb];
                if(j<i)continue;if(j>=N)continue;if(j-i>300)continue;
                if(do2opt(i,j)){imp=true;break;}}}
        }
        if(curCost<bestCost){bestCost=curCost;bestTour=tour;}
        if(!imp)break;
    }
    // Or-opt: relocate single city
    for(int pass=0;pass<50&&elapsed()<4.9;pass++){
        bool imp=false;
        for(int i=1;i<N&&elapsed()<4.9;i++){
            int city=tour[i];
            for(int nb:nn[city]){int j=pos[nb];
                if(j==i||j==i-1||j==i+1)continue;if(j<0||j>=N)continue;
                // try moving city from pos i to after pos j
                vector<int>nt(tour);nt.erase(nt.begin()+i);
                int ins=j>i?j:j+1;nt.insert(nt.begin()+ins,city);
                int lo=min(i,ins)-1;if(lo<1)lo=1;int hi=max(i,ins)+1;if(hi>N)hi=N;
                double oldC=0,newC=0;for(int s=lo;s<=hi;s++){oldC+=eCost(tour,s);newC+=eCost(nt,s);}
                if(newC<oldC-1e-10){tour=nt;curCost+=newC-oldC;bpos();imp=true;break;}
            }
        }
        if(curCost<bestCost){bestCost=curCost;bestTour=tour;}
        if(!imp)break;
    }
    cout<<N+1<<"\n";for(int i=0;i<=N;i++)cout<<bestTour[i]<<"\n";
}
